11:   const alibiPlaces = ['the all-night diner','the southbound tram','a payphone on Mercer Street','the hotel lobby','the 24-hour pharmacy','a late rehearsal at the Orpheum','the river ferry','the newsroom basement','a card game at the Halcyon','a taxi outside City Hall'];
