13:   const months = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
14:   const pick = (arr, n) => arr[((n % arr.length) + arr.length) % arr.length];
15:   const hash = n => { let x = Math.imul(n ^ 0x45d9f3b, 0x45d9f3b); x = Math.imul(x ^ (x >>> 16), 0x45d9f3b); return (x ^ (x >>> 16)) >>> 0; };
16:   const pad = n => String(n).padStart(3, '0');
17:   const makeCase = n => {
