40:       {icon:'⌕', type:'TRACE ANALYSIS', title:'Residue on the scene', body:`A trace of ${culprit.trace} was found on the inside edge of the service door. The lab matched the sample to material routinely used by ${culprit.name}. No other person of interest is known to handle it.`},
41:       {icon:'⌑', type:'SCENE PHOTOGRAPH', title:'The room was not locked', body:`The latch shows no sign of forced entry. A single set of fresh prints leads from the service entrance to the desk, then back out. The victim’s ${object} was found beside the desk, wiped clean.`},
42:       {icon:'◷', type:'TIMELINE', title:'The window of opportunity', body:`The coroner places the death between ${time} and ${pick(['10:10 PM','11:25 PM','12:40 AM','9:55 PM'], seed >>> 3)}. The nearest street clock stopped at ${time}. The access log records an unassigned entry during that same interval.`},
43:       {icon:'▤', type:'PROPERTY LOG', title:'Item recovered', body:`${object} was catalogued at the scene. The object itself is ordinary; the detail that matters is the ${culprit.trace} caught in its hinge. It links the person who handled it to the service entrance.`}
44:     ];
