88:   const documentMarkup = (doc,index) => `<article class="document"><div class="document-header"><span class="document-type"><span class="doc-icon">${doc.icon}</span>${escapeHtml(doc.type)}</span><span class="document-date">${current.month} ${String(current.day).padStart(2,'0')} · MCB</span></div><h3>${escapeHtml(doc.title)}</h3>${doc.body.split('\n').map(line=>`<p>${escapeHtml(line)}</p>`).join('')}<span class="evidence-tag">FILED · ${pad(current.id)}-${String((activeTab==='overview'?0:activeTab==='evidence'?20:40)+index+1).padStart(2,'0')}</span></article>`;
89:   const overviewDocs = c => [
