91:     {icon:'⌖',type:'INVESTIGATOR’S BRIEF',title:'People of interest',body:`${c.suspects.map(s=>`${s.name} — ${s.role}. Claims to have been at ${s.alibi}.`).join('\n')}\n\nPossible motive under review: ${c.motive}. Compare each account with the lab findings and the witness timeline.`}
92:   ];
93:   const renderDocs = () => {
94:     const docs = activeTab==='overview' ? overviewDocs(current) : activeTab==='evidence' ? current.evidence : current.reports;
