98:   const openCase = id => {
99:     current = cases[id-1]; if(!current)return;
100:     activeTab='overview'; $('archive-view').classList.add('hidden'); $('case-view').classList.remove('hidden'); $('crumb-current').textContent=`FILE ${pad(id)}`;
101:     $('detail-kicker').textContent=`CASE ${pad(id)} · ${saved.solved[id]?'CLOSED INVESTIGATION':'OPEN INVESTIGATION'}`;
102:     $('detail-title').innerHTML=`${escapeHtml(current.title)}<span class="title-period">.</span>`;
103:     $('detail-deck').textContent=`A night in ${current.month.toLowerCase()}. Four stories. One truth.`;
104:     $('detail-number').textContent=pad(id);
105:     $('case-meta').innerHTML=[['VICTIM',current.victim],['LOCATION',current.place],['DATE',`${current.month} ${String(current.day).padStart(2,'0')}`],['CAUSE OF DEATH','UNDER REVIEW']].map(([a,b])=>`<div class="meta-item"><small>${a}</small><strong>${escapeHtml(b)}</strong></div>`).join('');
