141:   $('help-button').addEventListener('click',()=>$('help-modal').classList.remove('hidden'));$('close-help').addEventListener('click',()=>$('help-modal').classList.add('hidden'));$('got-it').addEventListener('click',()=>$('help-modal').classList.add('hidden'));$('help-modal').addEventListener('click',e=>{if(e.target===$('help-modal'))$('help-modal').classList.add('hidden');});
142:   document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('search-input').focus();}if(e.key==='Escape')$('help-modal').classList.add('hidden');});
